int s[][N],n; 
int js(s,n) {
    int z,j,k,r,total=0; 
    int b[N][N]; 
    if(n>2)
        {
        for(z=0;z<n;z++) 
            {
            for(j=0;j<n-1;j++) 
                 for(k=0;k<n-1;k++){
                        if(k>=z) b[j][k]=s[j+1][k+1]; 
                        else b[j][k]=s[j+1][k];
                        }
            if(z%2==0) r=s[0][z]*js(b,n-1);  
            else r=(-1)*s[0][z]*js(b,n-1); 
            total=total+r; 
            } 
        } 
    else if(n==2)
       total=s[0][0]*s[1][1]-s[0][1]*s[1][0]; 
    return total; 
} 
